package net.battlespades.bot;
import java.util.*;
import java.util.function.IntBinaryOperator;
import net.battlespades.physics.PlayerPhysics.Vector;
import static net.battlespades.bot.BotState.*;
import static net.battlespades.bot.BotFoundationsTest.*;
import static net.battlespades.bot.BotSourceFixture.*;
import static org.junit.jupiter.api.Assertions.*;
import org.junit.jupiter.api.Test;
class BotLiveTest {
 static final Map<String,Object> SOURCE=read("bot-live");
 static List<Vector> vectors(Object o){return list(o).stream().map(BotFoundationsTest::vector).toList();}
 static RecoveryPlanning.World world(Map<String,Object> scene){var cells=new HashSet<>(list(scene.get("cells")).stream().map(BotFoundationsTest::cell).toList());boolean water=string(scene.get("name")).equals("water");return (x,y,z)->x>=0&&x<512&&y>=0&&y<512&&(water?z==239:z>=40&&z<=239||cells.contains(new Cell(x,y,z)));}
 static StructureCollapse.Approach approach(RecoveryPlanning.World w,Vector p,int limit){var j=new StructureCollapse.ApproachJob(w,p,limit,2,4);int calls=0;while(!j.advance(7))assertTrue(++calls<10000);return j.result();}
 static StructureCollapse.Plan cut(RecoveryPlanning.World w,List<Cell> support,int limit,int max){var j=new StructureCollapse.CutJob(w,support,40,limit,max,null);int calls=0;while(!j.advance(19))assertTrue(++calls<100000);return j.result();}
 @Test void everyToolUsesOnlySourceFirearmDoctrine(){for(var o:list(SOURCE.get("profiles"))){var r=map(o);int t=integer(r.get("tool"));matches(r.get("envelope"),BotCombatProfiles.envelope(t));matches(r.get("recoil"),BotCombatProfiles.recoil(t));}}
 @Test void boundedSupportFloodsAndVertexCutsMatchSource(){for(var o:list(SOURCE.get("scenes"))){var s=map(o);var w=world(s);var p=vector(s.get("position"));var hunters=vectors(s.get("hunters"));try{var support=StructureCollapse.support(w,p);matches(s.get("support"),support);matches(s.get("floor"),StructureCollapse.hordeFloor(w,p,hunters,12));for(var v:list(s.get("isolations"))){var r=map(v);var j=new StructureCollapse.IsolationJob(w,p,hunters,integer(r.get("limit")),1.5);while(!j.advance(3)){}matches(r.get("result"),j.result());}for(var v:list(s.get("approaches"))){var r=map(v);var a=approach(w,p,integer(r.get("limit")));Map<String,Object> value=null;if(a!=null){value=new LinkedHashMap<>();value.put("support_z",a.supportZ());value.put("closed",a.closed());value.put("frontier",a.frontier());value.put("radius",a.radius());value.put("steps",a.steps().entrySet().stream().map(e->{var row=new LinkedHashMap<String,Object>();row.put("cell",e.getKey());row.put("steps",e.getValue());row.put("toward",a.toward().get(e.getKey()));return row;}).toList());}matches(r.get("result"),value);for(var q:list(r.get("queries"))){var query=map(q);matches(query.get("moves"),a==null?null:a.movesFrom(vector(query.get("position"))));}}for(var v:list(s.get("cuts"))){var r=map(v);var plan=cut(w,support,integer(r.get("limit")),integer(r.get("max_cost")));matches(r.get("result"),plan);if(plan!=null)matches(r.get("falls"),StructureCollapse.fallsAfter(w,plan.cut(),support,10000));}}catch(AssertionError e){throw new AssertionError(s.get("name")+" structural planning",e);}}}
 @Test void hordeAllocatesAndRecoversAcrossConnectedRosterAndTerrainChanges(){for(var o:list(SOURCE.get("scenes"))){var s=map(o);var w=world(s);var p=vector(s.get("position"));var a=approach(w,p,700);var cut=cut(w,StructureCollapse.support(w,p),2500,48);var coordinator=new HordeCoordinator();for(var v:list(s.get("horde"))){var r=map(v);double now=real(r.get("now"));var members=list(r.get("zombies")).stream().map(x->{var m=map(x);return new HordeCoordinator.Member(integer(m.get("player_id")),vector(m.get("position")),bool(m.get("is_bot")),bool(m.get("can_dig")),bool(m.get("can_build")),bool(m.get("working")));}).toList();var targets=list(r.get("targets")).stream().map(x->{var m=map(x);return new HordeCoordinator.Target(integer(m.get("player_id")),vector(m.get("position")));}).toList();var siege=bool(r.get("siege"))?Map.of(20,new HordeCoordinator.Siege(a!=null&&a.closed(),40,cut,now,a,p)):Map.<Integer,HordeCoordinator.Siege>of();try{matches(r.get("orders"),coordinator.plan(members,targets,siege,now,w).values());matches(r.get("metrics"),coordinator.metrics());}catch(AssertionError e){throw new AssertionError(s.get("name")+" horde at "+now,e);}}}}
 @Test void refugeElectionRetainsBoundedWorkAndRegionFences(){for(var o:list(SOURCE.get("refuges"))){var r=map(o);String kind=string(r.get("kind"));IntBinaryOperator surface=(x,y)->(x-256)*(x-256)+(y-256)*(y-256)<36?30:kind.equals("shore")&&x<248?239:40;var election=new ZombieRefuge.Election(surface,vectors(r.get("survivors")),vectors(r.get("zombies")),vectors(r.get("exclude")),kind.equals("region")?(x,y)->x<256?1:2:null,56,4,integer(r.get("limit")));int calls=0;while(!election.advance(3))assertTrue(++calls<1000);matches(r.get("result"),election.result());}}
 @Test void seededChatRetainsTypingCooldownBacklogCombatAndResetSemantics(){for(var o:list(SOURCE.get("banter"))){var trace=map(o);var b=new BotBanter(number(trace.get("seed")));for(int j=0;j<24;j++)b.register(j,"Bot"+j);for(var v:list(trace.get("events"))){var r=map(v);int i=integer(r.get("i")),k=i%24,victim=(i+7)%24;double now=real(r.get("now"));switch(string(r.get("op"))){case "phase"->b.phase(now,i%22==0?"start":"end");case "forget"->b.forget(5);case "reset"->b.reset();case "kill"->b.killed(now,k,victim,"Bot"+k,"Bot"+victim,i%9,i,i%4==0,i%5==0);default->fail("Unknown event");}var busy=new HashSet<>(list(r.get("busy")).stream().map(BotFoundationsTest::integer).toList());try{matches(r.get("result"),b.due(now,busy).stream().map(l->List.of(l.playerId(),l.text())).toList());matches(r.get("queue"),b.queued());}catch(AssertionError e){throw new AssertionError("chat seed "+trace.get("seed")+" event "+i,e);}}}}
 @Test void mainBrainTargetGoalInventoryAndLaunchBoundariesMatchSource()throws Exception{var w=new BotNavigationWorld();w.load(new MapSnapshot(7,0,BotNavigationTest.raw(SOURCE.get("raw_zlib")),"tdm","",List.of(),"retail"));var state=new BotBrainState(7,1,1,-1,true);var memory=new BotModePolicies.Memory(new BotModePolicies());var launch=new BrainOriented();int index=0;for(var o:list(SOURCE.get("brain"))){var r=map(o);var f=BotPerceptionTestData.frame(r.get("frame"));var p=BotPlayerTestData.player(r.get("observer"));var d=BotPerceptionTestData.decision(r.get("decision"));var enemy=f.players().get(1);double now=f.createdAt();try{assertEquals(r.get("visible")==null?null:BotPlayerTestData.player(r.get("visible")),BrainTargeting.visible(w,f,p,state,d));matches(r.get("goal"),BrainGoals.select(w,memory,f,p,state,now,d));var choice=launch.choose(w,f,p,enemy,state,f.profile(),now);matches(r.get("choice"),choice==null?null:List.of(choice.tool(),choice.aimOffset()));BrainOriented.progress(state,p.position(),now);var inventory=map(r.get("inventory"));matches(inventory.get("weapon"),BrainInventory.weapon(p,10.+index%30));var wallet=BrainInventory.wallet(p,p.loadout().getFirst());matches(inventory.get("wallet"),List.of(wallet.clip(),wallet.reserve()));matches(inventory.get("melee"),BrainInventory.melee(p));matches(inventory.get("swing"),BrainInventory.swingInterval(BrainInventory.melee(p)));matches(inventory.get("sprint_room"),BrainInventory.sprintRoom(p));matches(inventory.get("uphill"),BrainInventory.sprintsUphill(p));matches(inventory.get("abilities"),BrainInventory.movementAbilities(p).stream().map(a->a.name().toLowerCase(Locale.ROOT)).sorted().toList());matches(r.get("contact"),Arrays.asList(state.contactId,state.contactGeneration,state.contactPosition,state.contactUntil,state.acquiredAt));matches(r.get("next_oriented"),state.nextOrientedAt);matches(r.get("progress"),Arrays.asList(state.combatProgressPosition,state.combatProgressAt,state.combatLastAt,state.combatStallStage));matches(r.get("lane"),BrainOriented.laneClear(f,p,enemy.eye()));matches(r.get("safe"),BrainOriented.safe(f,p,enemy.position(),p.loadout().getLast(),false));}catch(AssertionError e){throw new AssertionError("brain boundary "+index,e);}index++;}}
 @Test void siegeServiceBudgetsRetainedJobsAndDropsEpochState()throws Exception{var scene=map(list(SOURCE.get("scenes")).get(2));var terrain=world(scene);class LiveWorld implements ZombieSiegeService.World{java.util.function.Consumer<Cell> listener;int closed;boolean broken;public boolean solid(int x,int y,int z){if(broken)throw new IllegalStateException("lost map");return terrain.solid(x,y,z);}public AutoCloseable subscribe(java.util.function.Consumer<Cell> next){assertNull(listener);listener=next;return ()->{listener=null;closed++;};}}var w=new LiveWorld();double[] now={100},budget={0};var failures=new ArrayList<String>();var service=new ZombieSiegeService(.001,()->now[0],()->budget[0]+=.00002,(message,error)->failures.add(message));var zombies=List.of(new HordeCoordinator.Member(0,new Vector(18.5,24.5,37.75),true,true,true,false));var survivors=List.of(new HordeCoordinator.Target(20,vector(scene.get("position"))));for(int i=0;i<140;i++){now[0]=100+i*.1;double before=budget[0];var orders=service.objectives(7,1,true,3,zombies,survivors,w,now[0]);assertEquals(1,orders.size());assertTrue(budget[0]-before<.0013,"bounded call");}assertTrue(failures.isEmpty());assertTrue(service.stats().get("analyses")>0);assertTrue(service.stats().get("plans")>0);int analyses=service.stats().get("analyses");assertNotNull(w.listener);w.listener.accept(new Cell(24,24,25));for(int i=0;i<50;i++){now[0]+=.1;service.objectives(7,1,true,3,zombies,survivors,w,now[0]);}assertTrue(service.stats().get("analyses")>analyses);assertTrue(service.objectives(8,2,false,3,zombies,survivors,w,now[0]).isEmpty());assertNull(w.listener);assertTrue(service.lastOrders().isEmpty());assertTrue(service.debugRows().isEmpty());assertTrue(w.closed>0);var outside=new java.util.concurrent.atomic.AtomicReference<Throwable>();var thread=new Thread(()->{try{service.stats();}catch(Throwable error){outside.set(error);}});thread.start();thread.join();assertInstanceOf(IllegalStateException.class,outside.get());w.broken=true;service.objectives(8,2,true,3,zombies,survivors,w,now[0]);now[0]+=1;assertTrue(service.objectives(8,2,true,3,zombies,survivors,w,now[0]).isEmpty());assertEquals(1,failures.size());assertNull(w.listener);service.close();}
 @Test void visibleFightsRetainActualSourceWeaponFootworkAndActionOwnership()throws Exception{var w=new BotNavigationWorld();w.load(new MapSnapshot(7,0,BotNavigationTest.raw(SOURCE.get("raw_zlib")),"tdm","",List.of(),"retail"));double[] now={100};for(var o:list(SOURCE.get("combat"))){var trace=map(o);var state=new BotBrainState(7,1,1,-1,true);var combat=new BrainCombat(w,new BotAwareness(w),new BrainIntents(()->now[0]),new BrainOriented(),(frame,observer,held,goal,at)->{throw new AssertionError("Unexpected navigation in a source stationary-range combat trace");});int index=0;for(var v:list(trace.get("events"))){var r=map(v);var f=BotPerceptionTestData.frame(r.get("frame"));var p=BotPlayerTestData.player(r.get("observer"));var target=BotPlayerTestData.player(r.get("target"));now[0]=f.createdAt();state.acquiredAt=98;state.combatStallStage=integer(r.get("stage"));try{matches(observe(BotPerceptionTestData.intent(r.get("intent"))),combat.fight(f,p,target,state,f.profile(),now[0],null));}catch(AssertionError e){throw new AssertionError("weapon "+trace.get("weapon")+" combat boundary "+index,e);}index++;}}}
 @Test void routeOwnershipKeepsLiveEdgesAcrossNearbyErrandsAndBoundsTheirExpiry(){var state=new BotBrainState(7,1,1,-1,true);for(var o:list(SOURCE.get("routing"))){var r=map(o);int i=integer(r.get("i"));double now=real(r.get("now"));BotGoal goal=null;if(r.get("goal")!=null){var g=map(r.get("goal"));goal=new BotGoal(new ArrayList<>(list(g.get("key"))),vector(g.get("position")),string(g.get("role")),real(g.get("arrival_radius")),bool(g.get("sprint")),g.get("watch_position")==null?null:vector(g.get("watch_position")));}if(i%6==1)state.route=List.of(new RouteStep(new Vector(252,245.5,37.75),Affordance.WALK));BrainRoutingState.setGoal(state,goal,new Vector(245.5,245.5,37.75),now);var edge=list(r.get("edge"));BrainRoutingState.remember(state,new Edge(cell(edge.get(0)),cell(edge.get(1))),now,i%9-1);BrainRoutingState.prune(state,now);var actual=new LinkedHashMap<String,Object>();actual.put("goal",state.goal);actual.put("route",state.route);actual.put("blocked",state.blockedEdges.entrySet().stream().map(e->Map.of("source",e.getKey().source(),"target",e.getKey().target(),"until",e.getValue(),"since",state.blockedEdgeSince.get(e.getKey()))).toList());actual.put("retry",state.corridorRetryAt);actual.put("best",Double.isInfinite(state.goalBestDistance)?null:state.goalBestDistance);actual.put("progress",state.goalProgressAt);try{matches(r.get("state"),actual);}catch(AssertionError error){throw new AssertionError("route ownership "+i,error);}}}
 @Test void jetpackTakeoffCoastLandingAndFailedEdgesMatchSource(){double[] now={100};var intents=new BrainIntents(()->now[0]);for(var o:list(SOURCE.get("flights"))){var trace=map(o);int climb=integer(trace.get("climb"));var state=new BotBrainState(7,1,1,-1,true);state.flightSource=new Vector(245.5,245.5,37.75);state.flightStep=new RouteStep(new Vector(252.5,245.5,37.75-climb),Affordance.JETPACK);state.flightStartedAt=100;state.flightWatch=new Vector(270,245,37.75);for(var v:list(trace.get("events"))){var r=map(v);var f=BotPerceptionTestData.frame(r.get("frame"));var p=BotPlayerTestData.player(r.get("observer"));now[0]=f.createdAt();var flight=BrainMobility.flight(p,state,now[0]);var actual=flight==null?null:intents.emit(f,null,flight.movement(),flight.look(),flight.tool(),BotMessages.Action.none(),BotMessages.Priority.TRAVERSAL,false,false,flight.goal(),List.of(),flight.role(),true);matches(r.get("intent")==null?null:observe(BotPerceptionTestData.intent(r.get("intent"))),actual);matches(r.get("departed"),state.flightDeparted);matches(r.get("next_flight"),state.nextFlightAt);matches(r.get("remaining"),state.flightStep!=null);matches(r.get("blocked"),state.blockedEdges.entrySet().stream().map(e->Map.of("source",e.getKey().source(),"target",e.getKey().target(),"until",e.getValue())).toList());}}}
}
